{
  "name": "continual-learning",
  "version": "1.0.0",
  "description": "Incremental transcript-driven memory updates"
}

import FirecrawlApp from '@mendable/firecrawl-js';

const app = new FirecrawlApp({ apiKey: 'fc_api_key' });
const scrapeResult = await app.scrapeUrl('https://example.com', { formats: ['markdown'] });
console.log(scrapeResult.markdown);

server {
    listen 80;
    server_name example.com;
    location / {
        proxy_pass http://localhost:8080;
    }
}

const browser = await AgentBrowser.launch();
const page = await browser.open('https://example.com');
console.log(page.snapshot); // 텍스트 기반 트리 출력
